from pathlib import Path

path = Path('ios/LxMusicMobile/main.m')
text = path.read_text()

replacements = []

old_push = '''- (void)pushTemplate:(CPTemplate *)template {\n  CPInterfaceController *controller = self.interfaceController;\n  if (controller == nil || template == nil) return;\n  [controller pushTemplate:template animated:YES completion:nil];\n}\n'''
new_push = '''- (void)pushTemplate:(CPTemplate *)template {\n  CPInterfaceController *controller = self.interfaceController;\n  if (controller == nil || template == nil) return;\n  [controller pushTemplate:template animated:YES completion:^(BOOL success, NSError *error) {\n    if (!success) {\n      NSLog(@"[LXCarPlay] pushTemplate failed: %@", error);\n    }\n  }];\n}\n'''
replacements.append((old_push, new_push, 'pushTemplate'))

old_now = '''- (void)showNowPlaying {\n  CPInterfaceController *controller = self.interfaceController;\n  if (controller == nil) return;\n  CPNowPlayingTemplate *template = CPNowPlayingTemplate.sharedTemplate;\n  if (controller.topTemplate == template) return;\n  [controller pushTemplate:template animated:YES completion:nil];\n}\n'''
new_now = '''- (void)showNowPlaying {\n  CPInterfaceController *controller = self.interfaceController;\n  if (controller == nil) return;\n  CPNowPlayingTemplate *template = CPNowPlayingTemplate.sharedTemplate;\n  if (controller.topTemplate == template) return;\n  [self pushTemplate:template];\n}\n'''
replacements.append((old_now, new_now, 'showNowPlaying'))

old_root = '''- (void)buildRootTemplate {\n  self.homeTemplate = [[CPListTemplate alloc] initWithTitle:@"首页" sections:[self homeSections]];\n  self.homeTemplate.tabTitle = @"首页";\n  self.homeTemplate.tabImage = [self symbol:@"house.fill"];\n  self.homeTemplate.emptyViewTitleVariants = @[ @"LX Music" ];\n  self.homeTemplate.emptyViewSubtitleVariants = @[ @"请先在手机端打开一次 LX Music 完成音乐库同步" ];\n\n  self.libraryTemplate = [[CPListTemplate alloc] initWithTitle:@"音乐库" sections:[self librarySections]];\n  self.libraryTemplate.tabTitle = @"音乐库";\n  self.libraryTemplate.tabImage = [self symbol:@"music.note"];\n\n  self.playlistsTemplate = [[CPListTemplate alloc] initWithTitle:@"歌单" sections:[self playlistSectionsFromOffset:0]];\n  self.playlistsTemplate.tabTitle = @"歌单";\n  self.playlistsTemplate.tabImage = [self symbol:@"rectangle.stack.fill"];\n  self.playlistsTemplate.emptyViewTitleVariants = @[ @"暂无自建歌单" ];\n  self.playlistsTemplate.emptyViewSubtitleVariants = @[ @"可先在手机端创建歌单" ];\n\n  NSMutableArray<CPTemplate *> *tabs = [NSMutableArray arrayWithObjects:self.homeTemplate, self.libraryTemplate, self.playlistsTemplate, nil];\n  NSInteger maximumTabs = CPTabBarTemplate.maximumTabCount;\n  if (maximumTabs > 0 && tabs.count > (NSUInteger)maximumTabs) {\n    [tabs removeObjectsInRange:NSMakeRange((NSUInteger)maximumTabs, tabs.count - (NSUInteger)maximumTabs)];\n  }\n  self.tabBarTemplate = [[CPTabBarTemplate alloc] initWithTemplates:tabs];\n  [self.interfaceController setRootTemplate:self.tabBarTemplate animated:NO completion:nil];\n}\n'''
new_root = '''- (void)buildRootTemplate {\n  self.homeTemplate = [[CPListTemplate alloc] initWithTitle:@"首页" sections:[self homeSections]];\n  self.homeTemplate.tabTitle = @"首页";\n  self.homeTemplate.tabImage = [self symbol:@"house.fill"];\n  self.homeTemplate.emptyViewTitleVariants = @[ @"LX Music" ];\n  self.homeTemplate.emptyViewSubtitleVariants = @[ @"请先在手机端打开一次 LX Music 完成音乐库同步" ];\n\n  self.libraryTemplate = [[CPListTemplate alloc] initWithTitle:@"音乐库" sections:[self librarySections]];\n  self.libraryTemplate.tabTitle = @"音乐库";\n  self.libraryTemplate.tabImage = [self symbol:@"music.note"];\n\n  self.playlistsTemplate = [[CPListTemplate alloc] initWithTitle:@"歌单" sections:[self playlistSectionsFromOffset:0]];\n  self.playlistsTemplate.tabTitle = @"歌单";\n  self.playlistsTemplate.tabImage = [self symbol:@"rectangle.stack.fill"];\n  self.playlistsTemplate.emptyViewTitleVariants = @[ @"暂无自建歌单" ];\n  self.playlistsTemplate.emptyViewSubtitleVariants = @[ @"可先在手机端创建歌单" ];\n\n  CPInterfaceController *controller = self.interfaceController;\n  if (controller == nil) return;\n\n  CPTemplate *rootTemplate = self.homeTemplate;\n  self.tabBarTemplate = nil;\n  NSInteger maximumTabs = CPTabBarTemplate.maximumTabCount;\n  if (maximumTabs >= 2) {\n    NSMutableArray<CPTemplate *> *tabs = [NSMutableArray arrayWithObjects:self.homeTemplate, self.libraryTemplate, self.playlistsTemplate, nil];\n    if (tabs.count > (NSUInteger)maximumTabs) {\n      [tabs removeObjectsInRange:NSMakeRange((NSUInteger)maximumTabs, tabs.count - (NSUInteger)maximumTabs)];\n    }\n    @try {\n      self.tabBarTemplate = [[CPTabBarTemplate alloc] initWithTemplates:tabs];\n      rootTemplate = self.tabBarTemplate;\n    } @catch (NSException *exception) {\n      NSLog(@"[LXCarPlay] CPTabBarTemplate creation failed: %@", exception);\n      self.tabBarTemplate = nil;\n      rootTemplate = self.homeTemplate;\n    }\n  }\n\n  __weak typeof(self) weakSelf = self;\n  @try {\n    [controller setRootTemplate:rootTemplate animated:NO completion:^(BOOL success, NSError *error) {\n      if (success) return;\n      NSLog(@"[LXCarPlay] setRootTemplate failed: %@", error);\n      __strong typeof(weakSelf) self = weakSelf;\n      CPInterfaceController *liveController = self.interfaceController;\n      if (self == nil || liveController == nil || rootTemplate == self.homeTemplate) return;\n      [liveController setRootTemplate:self.homeTemplate animated:NO completion:^(BOOL fallbackSuccess, NSError *fallbackError) {\n        if (!fallbackSuccess) {\n          NSLog(@"[LXCarPlay] fallback root template failed: %@", fallbackError);\n        }\n      }];\n    }];\n  } @catch (NSException *exception) {\n    NSLog(@"[LXCarPlay] setRootTemplate exception: %@", exception);\n    if (rootTemplate != self.homeTemplate) {\n      [controller setRootTemplate:self.homeTemplate animated:NO completion:^(BOOL success, NSError *error) {\n        if (!success) NSLog(@"[LXCarPlay] exception fallback failed: %@", error);\n      }];\n    }\n  }\n}\n'''
replacements.append((old_root, new_root, 'buildRootTemplate'))

old_connect = '''  self.interfaceController = interfaceController;\n  [[NSNotificationCenter defaultCenter] addObserver:self\n                                           selector:@selector(handleLibraryChanged:)\n                                               name:LXCarPlayLibraryDidChangeNotification\n                                             object:nil];\n'''
new_connect = '''  self.interfaceController = interfaceController;\n  [[NSNotificationCenter defaultCenter] removeObserver:self\n                                                  name:LXCarPlayLibraryDidChangeNotification\n                                                object:nil];\n  [[NSNotificationCenter defaultCenter] addObserver:self\n                                           selector:@selector(handleLibraryChanged:)\n                                               name:LXCarPlayLibraryDidChangeNotification\n                                             object:nil];\n'''
replacements.append((old_connect, new_connect, 'observer dedupe'))

for old, new, name in replacements:
    if new in text:
        continue
    if old not in text:
        raise SystemExit(f'Missing stability patch anchor: {name}')
    text = text.replace(old, new, 1)

path.write_text(text)
